'use strict';
/*
 * model-echo.cjs — a zero-dependency example MYRIAD model.
 *
 * A MYRIAD model is just:  async (prompt, opts) => string | { text }
 * MYRIAD calls it once per variant; `opts.variant_idx` tells you which attempt this is.
 *
 * Point MYRIAD_MODEL at this file, or pass your own function as `model` to myriadCycle.
 * To use a real LLM, replace the body with a call to your provider:
 *
 *   module.exports = async (prompt, opts) => {
 *     const res = await fetch('https://api.your-provider.com/v1/chat/completions', {
 *       method: 'POST',
 *       headers: { Authorization: `Bearer ${process.env.YOUR_API_KEY}`, 'Content-Type': 'application/json' },
 *       body: JSON.stringify({ model: 'your-model', messages: [{ role: 'user', content: prompt }] }),
 *     });
 *     const j = await res.json();
 *     return j.choices?.[0]?.message?.content || '';
 *   };
 *
 * The stub below is deterministic and offline so this file runs as-is.
 */
module.exports = async function model(prompt, opts = {}) {
  const idx = opts.variant_idx != null ? opts.variant_idx : 0;
  const firstLine = String(prompt).split('\n').find(Boolean) || String(prompt);
  return `attempt#${idx}: ${firstLine.slice(0, 120)}`;
};
